    main()

from typing import List
import heapq
import random


class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        if m == 0:
            return n * (n + 1) // 2

        buckets = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            if x < y:
                a, b = x, y
            else:
                a, b = y, x
            buckets[b].append((a, idx))

        heap = []
        cnt = [0] * (n + 1)
        uid = [-1] * (n + 1)
        gain = [0] * m
        base = 0

        heappush = heapq.heappush
        heappop = heapq.heappop

        for r in range(1, n + 1):
            for a, idx in buckets[r]:
                if cnt[a] == 0:
                    heappush(heap, -a)
                    cnt[a] = 1
                    uid[a] = idx
                else:
                    cnt[a] += 1
                    uid[a] = -1

            if heap:
                top1 = heappop(heap)
                max_a = -top1
                second_a = -heap[0] if heap else 0
                heappush(heap, top1)

                base += r - max_a
                if cnt[max_a] == 1:
                    u = uid[max_a]
                    if u != -1:
                        gain[u] += max_a - second_a
            else:
                base += r

        return base + max(gain)


def _brute_max(n: int, pairs: List[List[int]]) -> int:
    norm = []
    for x, y in pairs:
        if x < y:
            norm.append((x, y))
        else:
            norm.append((y, x))

    m = len(norm)
    masks = [[0] * (n + 1) for _ in range(n + 1)]

    for l in range(1, n + 1):
        for r in range(l, n + 1):
            mask = 0
            for i, (a, b) in enumerate(norm):
                if a >= l and b <= r:
                    mask |= 1 << i
            masks[l][r] = mask

    best = 0
    for skip in range(m):
        keep = ((1 << m) - 1) ^ (1 << skip)
        valid = 0
        for l in range(1, n + 1):
            for r in range(l, n + 1):
                if (masks[l][r] & keep) == 0:
                    valid += 1
        if valid > best:
            best = valid

    return best


