    assert sol.distanceSum(2, 2, 2) == 8
    assert sol.distanceSum(1, 4, 3) == 20
    assert sol.distanceSum(1, 2, 2) == 1
    assert sol.distanceSum(2, 1, 2) == 1
    assert sol.distanceSum(3, 3, 9) == 72

